mapper.select:
SELECT COUNT(f.id) AS observation_count, COUNT(DISTINCT f.acq_date) AS observed_day_count, MIN(f.acq_datetime_kst) AS earliest_observation, MAX(f.acq_datetime_kst) AS latest_observation, AVG(f.frp) AS average_frp, MAX(f.frp) AS maximum_frp, SUM(f.frp) AS total_frp FROM (SELECT ST_MakeEnvelope(#{west}, #{south}, #{east}, #{north}, 4326) AS boundary) area LEFT JOIN fire_points f ON f.location && area.boundary AND ST_Covers(area.boundary, f.location)
AND f.period >= #{fromPeriod}
AND f.period <= #{toPeriod}
AND f.sensor = #{sensor}
AND f.confidence_level = #{confidenceLevel}

SELECT f.id, f.latitude, f.longitude, f.frp, f.confidence_level, f.sensor, f.acq_datetime_kst AS observed_at FROM fire_points f WHERE f.location && ST_MakeEnvelope(#{west}, #{south}, #{east}, #{north}, 4326) AND ST_Covers(ST_MakeEnvelope(#{west}, #{south}, #{east}, #{north}, 4326), f.location) AND f.period = #{period}
AND f.sensor = #{sensor}
AND f.confidence_level = #{confidenceLevel}
ORDER BY f.acq_datetime_kst DESC, f.id DESC LIMIT #{limit}

SELECT f.period, COUNT(*) AS observation_count, SUM(f.frp) AS total_frp, AVG(f.frp) AS average_frp FROM fire_points f WHERE f.location && ST_MakeEnvelope(#{west}, #{south}, #{east}, #{north}, 4326) AND ST_Covers(ST_MakeEnvelope(#{west}, #{south}, #{east}, #{north}, 4326), f.location) AND f.period >= #{fromPeriod} AND f.period <= #{toPeriod}
AND f.sensor = #{sensor}
GROUP BY f.period ORDER BY f.period

SELECT f.confidence_level, COUNT(*) AS observation_count, COUNT(*) * 100.0 / SUM(COUNT(*)) OVER () AS percentage FROM fire_points f WHERE f.location && ST_MakeEnvelope(#{west}, #{south}, #{east}, #{north}, 4326) AND ST_Covers(ST_MakeEnvelope(#{west}, #{south}, #{east}, #{north}, 4326), f.location) AND f.period >= #{fromPeriod} AND f.period <= #{toPeriod}
AND f.sensor = #{sensor}
GROUP BY f.confidence_level ORDER BY CASE f.confidence_level WHEN 'high' THEN 1 WHEN 'nominal' THEN 2 WHEN 'low' THEN 3 ELSE 4 END
